import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxTextareaField,
  JxButton,
  JxAlert,
} from '@jinx-ui/react';

interface RegistrationFormProps {
  onSubmit: (data: {
    name: string;
    email: string;
    address: string;
    city: string;
    postalCode: string;
  }) => void;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [address, setAddress] = useState('');
  const [city, setCity] = useState('');
  const [postalCode, setPostalCode] = useState('');

  const canGoNext = () => {
    if (step === 0) return name.trim() !== '' && email.trim() !== '';
    if (step === 1) return address.trim() !== '' && city.trim() !== '';
    return true;
  };

  const handleNext = () => {
    if (step < steps.length - 1) {
      setStep(step + 1);
    }
  };

  const handleBack = () => {
    if (step > 0) {
      setStep(step - 1);
    }
  };

  const handleSubmit = () => {
    onSubmit({ name, email, address, city, postalCode });
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        maxWidth: '480px',
      }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxInputField
            label="Имя"
            required
            value={name}
            onChange={(event) => setName(event.target.value)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={email}
            onChange={(event) => setEmail(event.target.value)}
          />
        </div>
      ) : null}

      {step === 1 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxTextareaField
            label="Адрес"
            required
            rows={3}
            value={address}
            onChange={(event) => setAddress(event.target.value)}
          />
          <JxInputField
            label="Город"
            required
            value={city}
            onChange={(event) => setCity(event.target.value)}
          />
          <JxInputField
            label="Индекс"
            value={postalCode}
            onChange={(event) => setPostalCode(event.target.value)}
          />
        </div>
      ) : null}

      {step === 2 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxAlert intent="info" title="Проверьте данные перед отправкой">
            <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
              <span>
                <strong>Имя:</strong> {name || '—'}
              </span>
              <span>
                <strong>Почта:</strong> {email || '—'}
              </span>
              <span>
                <strong>Адрес:</strong> {address || '—'}
              </span>
              <span>
                <strong>Город:</strong> {city || '—'}
              </span>
              <span>
                <strong>Индекс:</strong> {postalCode || '—'}
              </span>
            </div>
          </JxAlert>
        </div>
      ) : null}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: '8px' }}>
        <JxButton variant="ghost" onClick={handleBack} disabled={step === 0}>
          Назад
        </JxButton>
        {step < steps.length - 1 ? (
          <JxButton variant="primary" onClick={handleNext} disabled={!canGoNext()}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={handleSubmit}>
            Отправить
          </JxButton>
        )}
      </div>
    </div>
  );
}

